  if (ignoreList(buf))
    discard(size);

  else if (dataIgnoreList(buf))
    decodeBlock();

  else if (equalsQTimeTag(buf, "ftyp"))
    fileTypeDecoder(size);

  else if (equalsQTimeTag(buf, "trak"))
