      io_->read(buf.data(), 1);
      td2 = find(PictureControlAdjust, (int)buf.data()[0] & 7);
      if (td2)
        xmpData_["Xmp.video.PictureControlAdjust"] = exvGettext(td2->label_);
      else
        xmpData_["Xmp.video.PictureControlAdjust"] = (int)buf.data()[0] & 7;

