      td2 = find(NormalSoftHard, (int)buf.data()[0] & 7);
      if (td2)
        xmpData_["Xmp.video.PictureControlQuickAdjust"] = exvGettext(td2->label_);

      io_->read(buf.data(), 1);
      td2 = find(NormalSoftHard, (int)buf.data()[0] & 7);
      if (td2)
        xmpData_["Xmp.video.Sharpness"] = exvGettext(td2->label_);
